import { Routes } from '@angular/router';
import { FeatureIndex } from '../../shared/feature-index';
import { NodeDetail } from '../../shared/node-detail';
import { nodeDetailTitle, pageTitle } from '../../shared/route-title';
import mySectionContent from './my-section-content.json';

export const MY_SECTION_ROUTES: Routes = [
  { path: '', component: FeatureIndex, data: { content: mySectionContent, basePath: 'my-section' }, title: pageTitle('My Section') },
  { path: '**', component: NodeDetail, data: { content: mySectionContent, basePath: 'my-section', sectionLabel: 'My Section' }, title: nodeDetailTitle }
];

